		}
	}
}

func walkBlocks(bs []comment.Block, depth int) {
	for _, b := range bs {
		switch v := b.(type) {
		case *comment.Paragraph:
			fmt.Printf("%*sParagraph:\n", depth, "")
			walkTexts(v.Text, depth+2)
		case *comment.List:
