	t.Helper()
	fset := token.NewFileSet()
	pkgs := newPackages(t, target.pattern, fset)
	for _, pkg := range pkgs {
		if len(pkg.Errors) != 0 && !target.ignoreErrors {
			for _, err := range pkg.Errors {
				t.Error(err)
			}
			return
		}
		ctx := &linter.Context{
			SizesInfo: sizes,
			FileSet:   fset,
			TypesInfo: pkg.TypesInfo,
			Pkg:       pkg.Types,
		}
